    "text": "제대로 된 판단으로 매수한 우량주라면, 그것을 팔아야 할 때는 사실상 존재하지 않는다. 기업의 펀더멘털이 훼손되지 않았다면 일시적인 주가 하락은 매도의 이유가 되지 못한다. 좋은 기업을 오래 보유하는 인내심이야말로 진짜 수익을 만든다.",
