    "text": "돈을 잘 다루는 것은 당신이 얼마나 똑똑한지와는 큰 관련이 없고, 당신이 어떻게 행동하느냐와 훨씬 더 깊이 관련되어 있다. 그리고 행동은 아무리 똑똑한 사람이라도 가르치기 어렵다.",
    "title": "돈의 심리학 (The Psychology of Money)",
