    "text": "가치투자는 상당한 노력과 유별나게 엄격한 규율, 그리고 소수만이 기꺼이 받아들이는 장기적 투자 시야를 요구한다. 그럼에도 불구하고, 특히 시장이 빠르게 상승할 때 많은 투자자들은 큰 위험을 감수하지 않고 견실한 수익을 내는 데 만족하지 못한다. 그들은 손쉬운 돈이라는 붙잡기 어려운 유혹에 이끌린다.",
