    "text": "자신이 무엇을 소유하고 있는지, 그리고 왜 그것을 소유하고 있는지 알아야 한다. 이해하지 못하는 회사에 투자하는 것은 투자가 아니라 도박이다. 정말로 아는 기업에만 돈을 넣어라.",
