    "text": "누군가를 사랑하는 건 새 집으로 이사하는 것과 같다고, 소냐는 말하곤 했다. 세월이 흐르면 그 집을 완벽해서가 아니라, 완벽하지 않은 모든 점들 때문에 사랑하게 된다.",
