    "text": "사람들이 정말 중요하게 여기는 것에 의문을 던지고, 그들을 놀라게 할 답을 찾아낼 수 있다면, 즉 통념을 뒤엎을 수 있다면 운이 따를지도 모른다.",
    "title": "괴짜경제학",
