    "text": "경제학 교과서 속 '경제적 인간'은 아인슈타인처럼 사고하고 슈퍼컴퓨터만큼 기억하며 성인 같은 의지력을 지녔다. 하지만 우리가 아는 사람들은 호모 이코노미쿠스가 아니라 그냥 호모 사피엔스다.",
